import {actorLabel} from './admin-activity.mjs';
import {customerContactPanel} from './admin-customer-contact.mjs';
import {resendPanel} from './admin-resend.mjs';
import {dateTime} from './admin-order-state.mjs';
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
export function correspondencePanel(order,api,checkout){const panel=el('section');panel.className='order-contact';panel.append(customerContactPanel(order,checkout));const feedback=el('p'),history=el('div'),notes=el('div'),form=el('div'),kind=el('select');for(const [value,text] of [['note','Intern note · kun for Smerch'],['email','E-mail til kunden']]){const o=el('option',text);o.value=value;kind.append(o);}kind.setAttribute('aria-label','Beskedtype');const recipient=el('p'),subject=el('input'),text=el('textarea'),preview=el('button','Gennemse'),review=el('div');subject.value='Din Smerch-ordre '+(order.checkoutId||order.purchaseOrderNumber);subject.maxLength=160;subject.setAttribute('aria-label','Emne');text.maxLength=4000;text.rows=5;text.setAttribute('aria-label','Besked');const templates=el('select');templates.setAttribute('aria-label','Beskedskabelon');for(const [value,label] of [['','Vælg eventuelt en skabelon'],['Vi mangler en original logofil til din ordre. Vil du sende den som svar på denne mail?','Bed om logofil'],['Vi har brug for lidt flere oplysninger om din ordre:','Bed om oplysninger'],['Her er en opdatering på din ordre:','Ordreopdatering']]){const o=el('option',label);o.value=value;templates.append(o);}templates.onchange=()=>{text.value=templates.value;review.replaceChildren();};const update=()=>{subject.hidden=templates.hidden=kind.value!=='email';preview.textContent=kind.value==='note'?'Gem intern note':'Gennemse e-mail';recipient.textContent=kind.value==='email'?'Modtager: '+(order.shipping?.email||'Ingen e-mail registreret'):'Noten sendes ikke til kunden eller PF.';review.replaceChildren();};kind.onchange=update;subject.oninput=text.oninput=()=>review.replaceChildren();update();async function load(){try{const messages=await(await api(`/api/pf-orders/${order.id}/correspondence`)).json();history.replaceChildren(el('h3','Beskedhistorik'));notes.replaceChildren(el('h3','Gemte interne noter'));if(!messages.some(m=>m.kind==='note'))notes.append(el('p','Ingen interne noter gemt på ordren endnu.'));for(const m of [...messages].reverse()){const item=el(m.kind==='note'?'article':'details');item.append(el(m.kind==='note'?'strong':'summary',m.kind==='note'?'Intern note':m.subject),el('small',dateTime(m.createdAt)+' · '+({sent:'Accepteret af mailserver',saved:'Gemt internt',sending:'Afventer afsendelsesstatus',uncertain:'Afsendelse usikker'}[m.status]||m.status)),el('p',m.text));item.append(el('small','Udført af: '+actorLabel(m.initiatedBy)));if(m.kind==='email')item.append(el('small','Afsender: '+actorLabel(m.sentBy)));item.style.whiteSpace='pre-wrap';if(m.documentId){const doc=el('a','PDF-version '+(m.documentVersion||'')+' · åbn det sendte bilag');doc.href=`/api/pf-orders/${order.id}/documents/${m.documentId}`;doc.target='_blank';doc.rel='noopener';item.append(doc);}if(m.attachments?.length)item.append(el('small','Bilag: '+m.attachments.join(', ')));if(m.to)item.append(el('small','Til: '+m.to));if(m.error)item.append(el('p',m.error));(m.kind==='note'?notes:history).append(item);}notes.append(history);}catch(e){feedback.textContent=e.message;}}
preview.onclick=async()=>{review.replaceChildren();if(!text.value.trim()){feedback.textContent='Skriv først en besked.';return;}const payload={kind:kind.value,subject:subject.value,text:text.value,requestId:crypto.randomUUID()},send=el('button',kind.value==='note'?'Gem intern note':'Send e-mail til '+order.shipping?.email);review.append(el('h3','Gennemse før du sender'),el('p',payload.kind==='email'?payload.subject:'Intern note'),el('pre',payload.text),send);const save=async()=>{send.disabled=true;preview.disabled=true;try{const result=await(await api(`/api/pf-orders/${order.id}/correspondence`,'POST',payload)).json();feedback.textContent=result.status==='sent'?'Mailen er accepteret af mailserveren.':result.status==='saved'?'Noten er gemt.':result.error||'Afvent afsendelsesstatus.';text.value='';review.replaceChildren();await load();}catch(e){feedback.textContent=e.message+' Kontrollér historikken før du prøver igen.';await load();}finally{preview.disabled=false;}};send.onclick=save;if(payload.kind==='note'){review.replaceChildren();await save();}};form.append(kind,recipient,templates,subject,text,preview,review);feedback.setAttribute('role','status');notes.setAttribute('aria-label','Gemte interne noter');notes.className='order-contact-notes';form.className='order-contact-compose';panel.append(notes,resendPanel(order,api,load),form,feedback);load();return panel;}
